{
  "contract": "SafePaymentVault",
  "closure": {
    "site_function": "Withdraw",
    "site_call": ".call",
    "functions": [
      "GetTotalBalance",
      "MakeDeposit",
      "Withdraw"
    ],
    "justification": "All functions that interact with TotalBalance and _ethBal must be included to ensure soundness."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "GetTotalBalance",
      "MakeDeposit"
    ],
    "nesting_bound": {
      "Withdraw": 1
    }
  },
  "phases": {
    "function": "Withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ether in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_ethBal == TotalBalance + inFlight",
    "stable_formula": "_ethBal == TotalBalance",
    "kind": "additive"
  },
  "composition": {
    "target_property": "TotalBalance == _ethBal",
    "rule": "The exposure invariant ensures that any changes during the callback window are accounted for by the inFlight ghost variable."
  }
}
